import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

@NgModule({
  imports: [CommonModule],
  exports: []
})
export class SharedModule {}
```
In this example, we're creating a new module called `SharedModule` that imports the `CommonModule`, which provides basic Angular functionality.

2. **Create the shared component**: Create a new component file (e.g., `shared.component.ts`) inside the `shared` folder:
```typescript
// shared/shared.component.ts
import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'app-shared',
  template: '<p>Shared Component</p>'
})
export class SharedComponent implements OnInit {
  constructor() { }

  ngOnInit() { }
}
```
In this example, we're creating a simple component called `SharedComponent` that displays the text "Shared Component".

3. **Add the component to the shared module**: In the `SharedModule`, add the `SharedComponent` to the `exports` array so that it can be used across other modules:
```typescript
