```javascript
let angle = 0;

function setup() {
  createCanvas(600, 600, WEBGL);
  stroke(255);
  strokeWeight(2);
  noFill();
}

function draw() {
  background(0);
  translate(0, 0, -200);
  rotateY(angle);
  rotateX(angle);
  drawHeart();
  angle += 0.01;
}

function drawHeart() {
  push();
  translate(0, -150, 0);
  rotateZ(PI / 6);
  drawFractalHeart(200, 100);
  pop();
}

function drawFractalHeart(size, depth) {
  if (depth === 0) {
    return;
  }

  // draw a heart
  beginShape();
  vertex(-size/2, -size/2, 0);
  bezierVertex(-size/3, -size/2, -size/3, size/2, -size/2, size/2);
  bezierVertex(size/3, size/2, size/3, -size/2, size/2, -size/2);
  endShape();

  // draw the branches
  stroke(255, 0, 0);
  noFill();

  drawFractalHeart(size/3, depth - 1);

  push();
  translate(0, size/2, 0);
  rotateZ(PI / 3);
  drawFractalHeart(size/3, depth - 1);
  pop();

  push();
  translate(0, -size/2, 0);
  rotateZ(-PI / 3);
  drawFractalHeart(size/3, depth - 1);
  pop();
}
```

In this sketch, the `drawHeart` function draws the heart recursively by drawing a smaller heart and then rotating and translating to draw the branches of the heart. The `drawFractalHeart` function draws a heart of a given size and depth. The recursion stops when the depth reaches 0, at which point it simply returns without drawing anything.<|start_header_id|>assistant<|end_header_id|>

