using UnityEngine;

public class Board : MonoBehaviour
{
    public GameObject[,] gems; // Array de gemas (rows x columns)
    public int rows; // Número de filas
    public int columns; // Número de columnas
    public int gemWidth; // Ancho de cada gema
    public int gemHeight; // Alto de cada gema

    void Start()
    {
        // Inicializar el juego board
        gems = new GameObject[rows, columns];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                GameObject gem = GameObject.CreatePrimitive(PrimitiveType.Sphere); // Crear una esfera como gema
                gem.transform.parent = transform;
                gem.transform.localPosition = new Vector3(j * gemWidth, i * gemHeight, 0);
                gems[i, j] = gem;
            }
        }
    }
}
```
