import React, { useState, useEffect } from 'react';

const Autocomplete = ({ dataSource, initialValue = '', on SelectionChange }) => {
  const [inputValue, setInputValue] = useState(initialValue);
  const [suggestions, setSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const handleInputChange = (event) => {
      const inputValue = event.target.value;
      const suggestions = dataSource.filter((item) => item.toLowerCase().startsWith(inputValue.toLowerCase()));
      setSuggestions(suggestions);
      setActiveSuggestionIndex(-1);
    };
    document.addEventListener('input', handleInputChange);
    return () => document.removeEventListener('input', handleInputChange);
  }, [dataSource, initialValue]);

  const handleSuggestionClick = (suggestion) => {
    setInputValue(suggestion);
    onSelectionChange(suggestion);
  };

  const handleArrowKey = (event) => {
    event.preventDefault();
    if (activeSuggestionIndex === suggestions.length - 1) {
      return;
    }
    setActiveSuggestionIndex(activeSuggestionIndex + 1);
  };

  const handleEnterKey = (event) => {
    event.preventDefault();
    if (activeSuggestionIndex === -1) {
      return;
    }
    handleSuggestionClick(suggestions[activeSuggestionIndex]);
  };

  const handleEscapeKey = () => {
    setActiveSuggestionIndex(-1);
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={(event) => setInputValue(event.target.value)}
        placeholder="Search..."
        onFocus={() => setActiveSuggestionIndex(-1)}
        onKeyDown={(event) => {
          if (event.key === 'ArrowUp') handleArrowKey(event);
          if (event.key === 'ArrowDown') {
            event.preventDefault();
            setActiveSuggestionIndex((activeSuggestionIndex + 1) % suggestions.length);
          }
          if (event.key === 'Enter') handleEnterKey(event);
          if (event.key === 'Escape') handleEscapeKey();
        }}
      />
      {activeSuggestionIndex >= 0 && (
        <ul>
          {suggestions.map((suggestion, index) => (
            <li
              key={index}
              className={activeSuggestionIndex === index ? 'active' : ''}
              onClick={() => handleSuggestionClick(suggestion)}
            >
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
